import { describe, it, expect } from 'vitest';
import { assessCompleteness } from '../completeness.ts';
import fixture from './fixtures/corpus-counts.json' with { type: 'json' };

/**
 * Corpus replay — does Layer 1 agree with the human assessor on every real sheet?
 *
 * Synthetic tests prove the rules do what they say. This proves they say the
 * right thing. Each case reconstructs a response array matching what a real
 * candidate actually attempted, and asserts the rule reaches the same conclusion
 * the assessor reached in red pen.
 *
 * Fixture is pseudonymous and regenerated by scripts/build-count-fixture.mjs.
 */

type Entry = { attempted?: number; blanksStated?: number; assessorMarks?: string[] };
type Candidate = { id: string } & Partial<Record<'tat' | 'wat' | 'srt' | 'sdt', Entry>>;

const candidates = fixture.candidates as Candidate[];

/** n attempted responses padded to `total` with blanks. */
const sheet = (attempted: number, total: number) => [
  ...Array.from({ length: attempted }, () => 'He will act decisively.'),
  ...Array.from({ length: Math.max(0, total - attempted) }, () => null),
];

describe('corpus replay — SRT volume', () => {
  const withSrt = candidates.filter((c) => typeof c.srt?.attempted === 'number');

  it('has SRT counts for most of the corpus', () => {
    expect(withSrt.length).toBeGreaterThanOrEqual(9);
  });

  it.each(withSrt.map((c) => [c.id, c.srt!.attempted!] as const))(
    '%s attempted %i SRT — rule agrees with the assessor that this is short',
    (_id, attempted) => {
      const found = assessCompleteness({ instrument: 'srt', responses: sheet(attempted, 60) });
      const f = found.find((x) => x.code === 'attempts_below_target');
      expect(f).toBeDefined();
      expect(f!.observed).toBe(attempted);
      expect(f!.expected).toBe(45);
    },
  );

  it('flags every candidate in the corpus — no false negatives', () => {
    const missed = withSrt.filter(
      (c) =>
        !assessCompleteness({
          instrument: 'srt',
          responses: sheet(c.srt!.attempted!, 60),
        }).some((f) => f.code === 'attempts_below_target'),
    );
    expect(missed).toEqual([]);
  });

  it('reproduces the assessor own count in the message text', () => {
    for (const c of withSrt) {
      const [finding] = assessCompleteness({
        instrument: 'srt',
        responses: sheet(c.srt!.attempted!, 60),
      });
      expect(finding.message).toContain(String(c.srt!.attempted));
      expect(finding.message).toContain('45+');
    }
  });

  it('the corpus maximum still falls short of the stated target', () => {
    const max = Math.max(...withSrt.map((c) => c.srt!.attempted!));
    expect(max).toBeLessThan(45);
  });
});

describe('corpus replay — blank counting', () => {
  const cases = candidates.flatMap((c) =>
    (['tat', 'wat'] as const)
      .filter((k) => typeof c[k]?.blanksStated === 'number')
      .map((k) => [c.id, k, c[k]!.blanksStated!, c[k]!.attempted] as const),
  );

  it('has at least one stated blank count to replay', () => {
    expect(cases.length).toBeGreaterThan(0);
  });

  it.each(cases)('%s %s — rule counts the same %i blanks the assessor did', (_id, instrument, blanks) => {
    const total = instrument === 'tat' ? 12 : 60;
    const found = assessCompleteness({
      instrument,
      responses: sheet(total - blanks, total),
    });
    const f = found.find((x) => x.code === 'blank_responses');
    expect(f).toBeDefined();
    expect(f!.observed).toBe(blanks);
  });
});

describe('corpus replay — a full sheet raises nothing', () => {
  it('does not invent findings on a complete TAT', () => {
    expect(assessCompleteness({ instrument: 'tat', responses: sheet(12, 12) })).toHaveLength(0);
  });

  it('does not invent findings on a complete WAT', () => {
    expect(assessCompleteness({ instrument: 'wat', responses: sheet(60, 60) })).toHaveLength(0);
  });
});
